  /** @type {Array<{key: string, priority: number, seq: number}>} */
  #items = [];

  /** @type {Map<string, number>} Key to index in #items. */
  #index = new Map();

  /** @type {number} Next insertion sequence number. */
  #seq = 0;

  /** @returns {number} Number of entries currently held. */
